import os, re, json, sys

# Load all grids from the current session
def load():
    d = os.path.normpath(os.environ.get('RLM_SESSION_DIR', ''))
    sessions_path = d + '/../../sessions/'
    if not os.path.exists(sessions_path):
        return {}

    basename = os.path.basename(d)
    file_path = sessions_path + basename + '.jsonl'

    if not os.path.exists(file_path):
        return {}

    G = {}
    with open(file_path, 'r') as f:
        content = f.read().replace('\\n', '\n')

    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', content):
        k, h, w = m[1], int(m[2]), int(m[3])
        grid_str = content[m.end():].split('\n')[h]
        if k not in G and grid_str.strip():
            try:
                G[k] = [[int(x) for x in grid_str.split()] for x in []]
            except:
                pass
    return G

print("Loaded keys:", list(load().keys()))

import os, re

def load_grids():
    d = os.environ.get('RLM_SESSION_DIR', '')
    t = open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')
    lines = t.split('\n')

    grids = {}
    for i, line in enumerate(lines):
        if 'Test input' in line or 'Demo pair' in line:
            match = re.match(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\s*', line)
            if match:
                key = match.group(1)
                h = int(match.group(2))
                grid = []
                for row_idx in range(h):
                    row_line = lines[i + 1 + row_idx]
                    grid.append([int(x) for x in row_line.split()])
                grids[key] = grid
    return grids

G = load_grids()
print("Key:", list(G.keys())[0])
for key in G:
    print(f"\n=== {key} ===")
    print(repr(G[key]))

